import Button from "../ui/Button";

export default function LoginForm() {
  return (
    <div className="bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100 min-h-screen flex items-center justify-center px-4">
      <div className="md:flex md:space-x-12 items-center w-full max-w-6xl">
        {/* Branding Section */}
        <div className="md:w-1/2 text-center md:text-left mb-10 md:mb-0">
          <h1 className="text-blue-600 dark:text-blue-400 text-6xl font-bold">
            Eventry
          </h1>
          <p className="text-xl mt-4">
            Connect with friends and the world around you on Eventry.
          </p>
        </div>

        {/* Login Card */}
        <div className="bg-white dark:bg-gray-800 p-8 rounded-2xl shadow-lg w-full max-w-md">
          <form>
            <input
              type="email"
              placeholder="Enter email"
              className="w-full mb-4 px-4 py-3 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <input
              type="password"
              placeholder="Password"
              className="w-full mb-4 px-4 py-3 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 rounded-lg font-semibold hover:bg-blue-700 transition"
            >
              Log In
            </button>
          </form>

          <div className="text-center my-4">
            <a
              href="#"
              className="text-blue-600 dark:text-blue-400 text-sm hover:underline"
            >
              Forgotten password?
            </a>
            <p className="mx-1">or</p>
            <a
              href="#"
              className="text-blue-600 dark:text-blue-400 text-sm hover:underline"
            >
              Register?
            </a>
          </div>

          <hr className="my-4 border-gray-300 dark:border-gray-600" />

          <div className="flex justify-center">
            <Button>Register</Button>
          </div>
        </div>
      </div>
    </div>
  );
}
